/// `Conformance.Tree`: a collection of itself. Nothing but the depth counter bounds its nesting.
#[derive(Debug, Default, Clone, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize), serde(rename_all = "camelCase"))]
pub struct Tree(pub Vec<Option<Tree>>);

impl NinoRead for Tree {
    const MIN_SIZE: usize = 4;
    fn read(r: &mut Reader<'_>) -> Result<Self> {
        Self::read_option(r)?.ok_or_else(|| Error::of(ErrorKind::UnexpectedNull))
    }
    fn read_option(r: &mut Reader<'_>) -> Result<Option<Self>> {
        r.enter_struct()?;
        let v = <Option<Vec<Option<Tree>>>>::read(r);
        r.exit_struct();
        Ok(v?.map(Self))
    }
}

impl NinoWrite for Tree {
    fn write<'a>(&'a self, w: &mut Writer<'a>) -> Result<()> {
        self.0.write(w)
    }
    fn write_option<'a>(value: Option<&'a Self>, w: &mut Writer<'a>) -> Result<()> {
        <Vec<Option<Tree>> as NinoWrite>::write_option(value.map(|v| &v.0), w)
    }
}

impl J for Tree {
    fn j(&self) -> Value {
        self.0.j()
    }
}

