/// `Conformance.EmptyStruct`: raw, 1 bytes.
#[derive(Debug, Default, Clone, Copy, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize), serde(rename_all = "camelCase"))]
pub struct EmptyStruct {}

impl nino::Raw for EmptyStruct {
    const SIZE: usize = 1;
    const ALIGN: usize = 1;

    fn decode_raw(b: &[u8]) -> Result<Self> {
        let b = b.get(..1).ok_or_else(|| Error::of(ErrorKind::UnexpectedEnd))?;
        if [0].iter().any(|&i| b.get(i) != Some(&0)) {
            return Err(Error::of(ErrorKind::InvalidBits));
        }
        Ok(Self {})
    }

    fn encode_raw(&self, out: &mut [u8]) {
        let _ = out;
    }
}

impl NinoRead for EmptyStruct {
    const MIN_SIZE: usize = 1;

    fn read(r: &mut Reader<'_>) -> Result<Self> {
        <Self as nino::Raw>::decode_raw(&r.array::<1>()?)
    }
}

impl NinoWrite for EmptyStruct {
    fn write<'a>(&'a self, w: &mut Writer<'a>) -> Result<()> {
        let mut b = [0u8; 1];
        nino::Raw::encode_raw(self, &mut b);
        w.array(b);
        Ok(())
    }
}

impl J for EmptyStruct {
    fn j(&self) -> Value {
        let mut m = Map::new();
        m.insert("$type".into(), Value::from("Conformance.EmptyStruct"));
        Value::Object(m)
    }
}

/// `Conformance.Vec2`: raw, 8 bytes.
#[derive(Debug, Default, Clone, Copy, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize), serde(rename_all = "camelCase"))]
pub struct Vec2 {
    pub x: f32,
    pub y: f32,
}

impl nino::Raw for Vec2 {
    const SIZE: usize = 8;
    const ALIGN: usize = 4;

    fn decode_raw(b: &[u8]) -> Result<Self> {
        let b = b.get(..8).ok_or_else(|| Error::of(ErrorKind::UnexpectedEnd))?;
        Ok(Self {
            x: <f32 as nino::Raw>::decode_raw(b.get(0..).unwrap_or_default())?,
            y: <f32 as nino::Raw>::decode_raw(b.get(4..).unwrap_or_default())?,
        })
    }

    fn encode_raw(&self, out: &mut [u8]) {
        if let Some(o) = out.get_mut(0..) {
            nino::Raw::encode_raw(&self.x, o);
        }
        if let Some(o) = out.get_mut(4..) {
            nino::Raw::encode_raw(&self.y, o);
        }
    }
}

